export async function listTools() {
  return [{
    name: 'catalog_search',
    description: 'Search catalog items by name',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Search query' },
        offset: { type: 'integer', description: 'Pagination offset', default: 0 },
        limit: { type: 'integer', description: 'Page size', default: 2, minimum: 1, maximum: 5 }
      },
      required: ['query'],
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'catalog_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate args
  if (typeof args.query !== 'string') {
    throw new Error('query must be a string');
  }

  const offset = args.offset ?? 0;
  const limit = args.limit ?? 2;

  if (!Number.isInteger(offset) || offset < 0) {
    throw new Error('offset must be a non-negative integer');
  }
  if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
    throw new Error('limit must be an integer between 1 and 5');
  }

  // Check for extra properties
  const allowed = ['query', 'offset', 'limit'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Unexpected argument: ${key}`);
    }
  }

  // Case-insensitive search
  const query = args.query.toLowerCase();
  const matches = items.filter(item => item.name.toLowerCase().includes(query));

  // Paginate
  const page = matches.slice(offset, offset + limit);
  const nextOffset = offset + limit;
  const hasMore = nextOffset < matches.length;

  let text = JSON.stringify(page);
  if (hasMore) {
    text += `\nnext_offset: ${nextOffset}`;
  }

  return { content: [{ type: 'text', text }] };
}
